-- Oracle. Consulta de referencia de enero, sin credenciales.
SELECT r.ID_SOCIEDAD,r.ID_EMPLEADO,r.FEC_ALTA_EMPLEADO,r.FEC_IMPUTACION,r.FEC_PAGO,r.TP_IMPUT,r.CONTADOR_LIQ,r.TOT_REMUN_27617,r.TOT_RETEN,r.LIQUIDO,r3.ID_BUQUE,r3.ID_MAREA FROM ARBPRO.M4T_ACUMULADO_RL r LEFT JOIN ARBPRO.M4T_ACUMULADO_RL3 r3 ON r3.ID_SOCIEDAD=r.ID_SOCIEDAD AND r3.ID_EMPLEADO=r.ID_EMPLEADO AND r3.FEC_ALTA_EMPLEADO=r.FEC_ALTA_EMPLEADO AND r3.FEC_IMPUTACION=r.FEC_IMPUTACION AND r3.FEC_PAGO=r.FEC_PAGO WHERE r.FEC_IMPUTACION>=DATE '2026-01-01' AND r.FEC_IMPUTACION<DATE '2026-02-01' ORDER BY r.ID_EMPLEADO,r.CONTADOR_LIQ